<?php
declare(strict_types=1);namespace Tests\Feature;use App\Application\Projects\ProjectMatchingConfiguration;use App\Application\Projects\ProjectMatchingEngine;use App\Models\CapabilityStatement;use App\Models\PersonProfile;use App\Models\PortalAdministrator;use App\Models\PortalSetting;use App\Models\Project;use App\Models\ProjectMatchDecision;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Http;use Illuminate\Support\Str;use Tests\TestCase;
final class ProjectMatchingTest extends TestCase{use RefreshDatabase;public function test_only_consented_discoverable_capabilities_match():void{$p=$this->project();$this->profile('IDN-GOOD','Awa',true,true,'Développement web');$this->profile('IDN-PRIVATE','Privé',true,false,'Développement web');$r=app(ProjectMatchingEngine::class)->forProject($p,'IDN-OWNER',(new ProjectMatchingConfiguration)->defaults());self::assertCount(1,$r);self::assertSame('Awa',$r[0]['profile']->discovery_display_name);self::assertStringContainsString('recherchée par le projet',$r[0]['reasons'][0]);}public function test_no_required_capability_means_no_invented_match():void{$p=$this->project([]);self::assertSame([],app(ProjectMatchingEngine::class)->forProject($p,'IDN-OWNER',(new ProjectMatchingConfiguration)->defaults()));}public function test_hidden_decision_is_scoped_to_project_and_actor():void{$p=$this->project();$profile=$this->profile('IDN-GOOD','Awa',true,true,'Développement web');ProjectMatchDecision::query()->create(['project_id'=>$p->id,'actor_core_reference'=>'IDN-OWNER','subject_profile_reference'=>$profile->discovery_reference,'decision'=>'HIDDEN']);self::assertSame([],app(ProjectMatchingEngine::class)->forProject($p,'IDN-OWNER',(new ProjectMatchingConfiguration)->defaults()));self::assertCount(1,app(ProjectMatchingEngine::class)->forProject($p,'IDN-OTHER',(new ProjectMatchingConfiguration)->defaults()));}public function test_matching_never_assigns_or_creates_project_membership():void{$p=$this->project();$this->profile('IDN-GOOD','Awa',true,true,'Développement web');app(ProjectMatchingEngine::class)->forProject($p,'IDN-OWNER',(new ProjectMatchingConfiguration)->defaults());self::assertFalse(\Illuminate\Support\Facades\Schema::hasTable('dg_project_memberships'));self::assertSame(0,$p->events()->count());}public function test_admin_configures_matching_without_score():void{PortalAdministrator::query()->create(['core_identity_reference'=>'IDN-ADMIN']);$this->signIn('IDN-ADMIN');$this->put('/administration/correspondances-projets',['page_title'=>'Capacités utiles','page_intro'=>'Des raisons compréhensibles et consenties.','candidate_pool'=>80,'max_results'=>12,'max_reasons'=>3,'location_context'=>1])->assertRedirect();$s=PortalSetting::query()->findOrFail(ProjectMatchingConfiguration::KEY);self::assertSame(12,$s->value['max_results']);self::assertFalse($s->value['participation_context']);}private function project(array $caps=['Développement web']):Project{return Project::query()->create(['public_reference'=>(string)Str::uuid(),'owner_type'=>'PERSON','owner_reference'=>'IDN-OWNER','initiator_core_reference'=>'IDN-OWNER','name'=>'Projet test','summary'=>'Résumé réel du projet suffisamment détaillé.','problem'=>'Problème','proposed_solution'=>'Solution','beneficiaries'=>'Bénéficiaires','domain'=>'DIGITAL','participation_mode'=>'HYBRID','objectives'=>[],'required_capabilities'=>$caps,'required_resources'=>[],'risks'=>[],'property_regime'=>'PERSONAL_SUPPORTED','visibility'=>'PUBLIC','status'=>'PROPOSED','maturity'=>'IDEA']);}private function profile(string $id,string $name,bool $orientation,bool $discoverable,string $label):PersonProfile{$p=PersonProfile::query()->create(['core_identity_reference'=>$id,'discovery_reference'=>(string)Str::uuid(),'discovery_display_name'=>$name,'orientation_consent'=>$orientation,'discovery_consent'=>$discoverable,'participation_mode'=>'HYBRID']);CapabilityStatement::query()->create(['core_identity_reference'=>$id,'kind'=>'POSSESSED','label'=>$label,'normalized_label'=>mb_strtolower($label),'visibility'=>$discoverable?'DISCOVERABLE':'PRIVATE','matching_consent'=>true]);return $p;}private function signIn(string $r):void{Http::fake(['core.test/api/v1/sessions'=>Http::response(['jeton'=>'bearer','entite'=>$r,'assurance'=>'AS1','expire_le'=>'2026-08-16T23:59:00+00:00'],201),'core.test/api/v1/identites/*'=>Http::response(['reference'=>$r,'type'=>'personne','libelle'=>'Admin','etat'=>'ACTIF','source'=>'CORE','regime'=>'INSCRIT_AU_REGISTRE']),'core.test/api/v1/sessions/current'=>Http::response(['entite'=>$r,'assurance'=>'AS1','expire_le'=>'2026-08-16T23:59:00+00:00'])]);$this->post('/connexion',['identifier'=>$r,'secret'=>'secret']);}}
